local target = {
    enabled = true,
    position = CFrame.new(0,0,0)
}

local Hooks = {}

Hooks.Mouse = hookmetamethod(game, "__index", newcclosure(function(self, key)
    if target.enabled and target.position and self:IsA("Mouse") and key == 'Hit' then
        return target.position
    end

    return Hooks.Mouse(self, key)
end))

local target = {
    enabled = true,
    value = '...'
    position = Vector3.new(0,0,0),
    part = cloneref(game:GetService("Players"))[target.value].Character.Head
}

local Hooks = {}

Hooks.Remote = hookmetamethod(game, "__namecall", newcclosure(function(self, ...)
    local args = { ... }
    local method = getnamecallmethod():lower()

    if target.enabled and target.position and target.part and method == 'fireserver' and self.Name == 'MainEvent' and args[1] == 'ShootGun' then
        args[4] = target.position
        args[5] = target.part
        return Hooks.Remote(self, unpack(args))
    end

    return Hooks.Remote(self, ...)
end))
